from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    sum_result = sum(numbers)
    product_result = 1
    for number in numbers:
        product_result *= number
    return (sum_result, product_result)

from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    """ From a list of integers, remove all elements that occur more than once.\n    Keep order of elements left the same as in the input.\n    >>> remove_duplicates([1, 2, 3, 2, 4])\n    [1, 3, 4]\n    """  
    counts = {}
    # Count occurrences of each number
    for number in numbers:
        counts[number] = counts.get(number, 0) + 1
    # Return the list of numbers that occur only once
    return [number for number in numbers if counts[number] == 1]

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if (i % 11 == 0) or (i % 13 == 0):
            count += str(i).count('7')
    return count

def median(l: list):
    """Return median of elements in the list l."""
    l_sorted = sorted(l)
    n = len(l_sorted)
    mid = n // 2
    if n % 2 == 1:
        return l_sorted[mid]
    else:
        return (l_sorted[mid - 1] + l_sorted[mid]) / 2.0

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    largest_factor = 1
    # Check for the number of 2s that divide n
    while n % 2 == 0:
        largest_factor = 2
        n //= 2
    # n must be odd at this point, so a skip of 2 is possible (i.e., check only odd numbers)
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        largest_factor = n
    return largest_factor

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':  
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def vowels_count(s):
    vowels = 'aeiou'
    count = 0
    for i, char in enumerate(s.lower()):
        if char in vowels:
            count += 1
        elif char == 'y' and i == len(s) - 1:
            count += 1
    return count

