def anti_shuffle(s):
    result = []
    word = ''
    for char in s:
        if char == ' ':
            if word:
                result.append(''.join(sorted(word)))
                word = ''
            result.append(' ')
        elif char.isalnum() or char in '!@#$%^&*()-_=+[]{}|;:",.<>?/~`':
            word += char
    if word:
        result.append(''.join(sorted(word)))
    return ''.join(result)

def max_fill(grid, capacity):
    total_fills = 0
    for well in grid:
        total_water = sum(well)
        total_fills += (total_water + capacity - 1) // capacity
    return total_fills

def minPath(grid, k):
    from heapq import heappop, heappush
    import itertools

    N = len(grid)
    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the minimum value cell to start with
    min_value = float('inf')
    start_positions = []
    for r in range(N):
        for c in range(N):
            if grid[r][c] < min_value:
                min_value = grid[r][c]
                start_positions = [(r, c)]
            elif grid[r][c] == min_value:
                start_positions.append((r, c))

    # Priority queue to explore paths
    pq = []
    for start in start_positions:
        heappush(pq, (grid[start[0]][start[1]], start[0], start[1], 1, [grid[start[0]][start[1]]]))

    while pq:
        current_value, x, y, length, path = heappop(pq)

        if length == k:
            return path

        for dx, dy in directions:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < N and 0 <= new_y < N:
                heappush(pq, (grid[new_x][new_y], new_x, new_y, length + 1, path + [grid[new_x][new_y]]))

    return []

def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            total += num ** 2
        elif i % 4 == 0:
            total += num ** 3
        else:
            total += num
    return total

def x_or_y(n, x, y):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return x if is_prime(n) else y

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
